/**
 * Sumber tunggal warna status Deviasi.
 * DISAMAKAN dengan Document States (meta.states) doctype "Deviasi" — itulah warna
 * yang dipakai indikator Frappe (form & list) untuk status ini. Dipakai untuk pill
 * status di list card portal.
 */

// status → nama warna Frappe (persis dari Document States doctype "Deviasi").
const STATE_COLOR = {
	Draft: 'blue',
	'Request Approval Pengawas': 'pink',
	'Request Approval Ketua': 'purple',
	Approved: 'green',
	'Pengawas Reject': 'red',
	Rejected: 'red',
	Cancelled: 'red',
}

// Daftar status (urut sesuai alur approval). Sumber tunggal supaya selaras dengan
// warna di STATE_COLOR. Berguna nanti untuk filter status.
export const STATUS_OPTIONS = Object.keys(STATE_COLOR)

// Tebak warna untuk status tak terdaftar — meniru frappe.utils.guess_colour.
function guessColor(status) {
	const s = String(status || '')
	if (/Pending|Review|Request|Not Approved/i.test(s)) return 'orange'
	if (/Reject|Failed|Error|Cancel/i.test(s)) return 'red'
	if (/Approved|Done|Success|Active/i.test(s)) return 'green'
	if (/Draft|Submitted/i.test(s)) return 'blue'
	return 'gray'
}

export function statusColor(status) {
	return STATE_COLOR[status] || guessColor(status)
}

// Pill (bg + teks) untuk badge status di card.
const PILL = {
	gray: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	blue: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	orange: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	green: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	red: 'bg-ui-surface-red-100 text-ui-ink-red-700',
	pink: 'bg-ui-surface-pink-100 text-ui-ink-pink-700',
	purple: 'bg-ui-surface-purple-100 text-ui-ink-purple-700',
}
export function statusPillClass(status) {
	return PILL[statusColor(status)] || PILL.gray
}

// Titik (border lingkaran) untuk picker status di sheet filter.
const DOT = {
	gray: 'border-ui-line-gray-400',
	blue: 'border-ui-line-blue-500',
	orange: 'border-ui-line-orange-500',
	green: 'border-ui-line-green-500',
	red: 'border-ui-line-red-500',
	pink: 'border-ui-line-pink-500',
	purple: 'border-ui-line-purple-500',
}
export function statusDotClass(status) {
	return DOT[statusColor(status)] || DOT.gray
}

// Opsi Jenis Deviasi (dari Select field doctype "Deviasi"). Dipakai picker filter.
export const JENIS_DEVIASI_OPTIONS = [
	'Pengurangan Bunga',
	'Pengurangan Denda',
	'Pengurangan Bunga & Denda',
]
